    // Single public test function
    // Params:
    //  - depositAmount: amount to send to c via fallback (may be zero)
    //  - actionValue: amount requested when calling withdraw/sendMoney
    //  - useSendMoney: if true call sendMoney, else call withdraw
    function run(uint depositAmount, uint actionValue, bool useSendMoney) public payable {
        // ensure this test contract has enough Ether to deposit into c if desired
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // observe initial public state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // perform deposit by invoking fallback (top-level low-level call to trigger payable fallback)
        (bool depositOk, ) = address(c).call{value: depositAmount}("");

        // observe after deposit
        uint midBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Now attempt the owner-only action using direct typed calls (top-level)
        bool actionReverted;
        if (useSendMoney) {
            try c.sendMoney(address(this), actionValue) {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        } else {
            try c.withdraw(actionValue) {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        }

        // observe final public state
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule asserted:
        // 1) depositsCount increased by either 0 or 1 as a result of our single fallback attempt
        // 2) c.balance never increased due to withdraw/sendMoney attempts: finalBalance <= midBalance
        // 3) if the action reverted, c.balance is unchanged by that action: finalBalance == midBalance
        // 4) if the action succeeded, c.balance decreased by at most actionValue: midBalance - finalBalance <= actionValue
        assert(
            (finalDeposits == beforeDeposits || finalDeposits == beforeDeposits + 1)
            && finalBalance <= midBalance
            && (actionReverted ? finalBalance == midBalance : (midBalance - finalBalance <= actionValue))
        );
    }
}

