contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Fallback to accept Ether when C sends to this contract
    receive() external payable {}

    // Single public test function: try to call withdraw/withdrawAll/sendMoney as non-owner
    function run(address target, uint amount, uint sendToC) public payable {
        // sendToC is amount of wei to forward to c to ensure it has balance
        require(address(this).balance >= sendToC, "insufficient balance to fund c");
        // Fund c so withdraw/sendMoney could possibly transfer out
        // This is a state-changing call on c that increases its balance via fallback
        // We must call it as top-level statement
        (bool s,) = address(c).call{value: sendToC}("");
        // ensure funding succeeded for meaningful test
        require(s, "funding c failed");

        // Record balance before attempts
        uint before = address(c).balance;

        // Attempt withdraw as non-owner (this contract is NOT the owner because owner was set to msg.sender at C construction)
        bool withdrew;
        try c.withdraw(amount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // Attempt withdrawAll as non-owner
        bool withdrewAll;
        try c.withdrawAll() {
            withdrewAll = true;
        } catch {
            withdrewAll = false;
        }

        // Attempt sendMoney as non-owner
        bool sent;
        try c.sendMoney(target, amount) {
            sent = true;
        } catch {
            sent = false;
        }

        // After all attempts, ensure that if any non-owner call did not revert (i.e., returned true),
        // then address(c).balance decreased appropriately; otherwise balance must remain unchanged.
        uint after = address(c).balance;

        // General rule asserted: If none of the calls succeeded (all reverted), balance is unchanged.
        // If any succeeded, at least one of them must have decreased the contract balance by <= before,
        // and after == before - deducted where deducted is a value in [0, before].
        // We express this by: either (no call succeeded AND after == before) OR (some call succeeded AND after <= before).
        assert((!withdrew && !withdrewAll && !sent && after == before) || ( (withdrew || withdrewAll || sent) && after <= before));
    }
}

