    receive() external payable {}

    // We call run with: times = number of fallback calls to perform, each call sending 'each' wei; fundBefore is extra funding to ensure this contract can send
    function run(address payable targetUnused, uint times, uint each, uint fundBefore) public payable {
        require(address(this).balance >= fundBefore + times * each, "insufficient balance to fund/test");

        // Optionally fund c once before performing the measured fallback calls
        if (fundBefore > 0) {
            // Call c's fallback by sending Ether directly to its address
            (bool ok1, ) = address(c).call{value: fundBefore}("");
            require(ok1, "initial funding failed");
        }

        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Perform 'times' fallback calls, each sending 'each' wei
        for (uint i = 0; i < times; i++) {
            (bool ok, ) = address(c).call{value: each}("");
            require(ok, "fallback call failed");
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // The general rule: depositsCount increases by times, and balance increases by times*each
        assert(afterDeposits == beforeDeposits + times && afterBal == beforeBal + times * each);
    }
}

