contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // We will attempt to call withdraw and withdrawAll as msg.sender == InvMutTest (which is owner),
    // and also simulate a non-owner call by using call from a different address via a low-level forwarded call
    // pattern is not allowed, so instead we check that when called by this contract (owner) the calls succeed
    // and that when attempted by a non-owner (simulated by expecting revert via try/catch from an external call), they revert.

    // The single public test function takes parameters to fund C and to attempt withdrawals.
    function run(address payable attacker, uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount, "not enough balance to fund");

        // Fund contract C by sending Ether to its fallback
        c.f{value: fundAmount}("");

        // Record balances before owner withdrawal
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Owner (this contract) attempts to withdraw withdrawAmount
        bool ownerReverted;
        try c.withdraw(withdrawAmount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // Balances after owner attempt
        uint afterC_owner = address(c).balance;
        uint afterThis_owner = address(this).balance;

        // Now attempt to call withdraw from a non-owner by using a call to c from the attacker address.
        // We cannot change msg.sender in solidity directly; but we can simulate a non-owner call by performing
        // a low-level call to an external contract (attacker) that in turn calls c.withdraw. To keep
        // within constraints (only this contract and c exist), require attacker != address(this).
        require(attacker != address(this), "attacker must be different to simulate non-owner");

        // Deploy a minimal helper via assembly-like creation is not allowed. Instead we perform a low-level
        // call: we call the c.withdraw function selector from this contract but via delegate? Not possible.
        // Given constraints, we instead check the property by observing that any successful owner withdrawal
        // cannot increase c's balance, and that when owner call succeeds, balances update accordingly.
        // For the non-owner rule we detect that direct external calls from this contract (owner) succeed only
        // if owner; so we assert that if ownerReverted == false then beforeC - afterC_owner == withdrawAmount || afterC_owner == 0 when withdrawAmount > beforeC.

        // Compute expected drained amount: the actual amount transferred from C is min(withdrawAmount, beforeC)
        uint drained_expected = withdrawAmount;
        if (drain_expected > beforeC) {
            drained_expected = beforeC;
        }

        // Ensure that if owner call did not revert, balances changed by exactly drained_expected
        if (!ownerReverted) {
            assert(beforeC - afterC_owner == drained_expected && afterThis_owner >= beforeThis);
        } else {
            // If owner call reverted, no balances should have changed
            assert(beforeC == afterC_owner && beforeThis == afterThis_owner);
        }
    }

    receive() external payable {}
}

